import './App.css';

const authenticationSuccess = function() {
  const token = window.Trello.token();
  sessionStorage.setItem({'trelloToken': token});
  console.log('Successful authentication');
};

const authenticationFailure = function() {
  console.log('Failed authentication');
};

function App() {
  const handleLogin = ()=>{
      window.Trello.authorize({
      type: 'popup',
      name: 'Getting Started Application',
      scope: {
        read: 'true',
        write: 'true' },
      expiration: 'never',
      success: authenticationSuccess,
      error: authenticationFailure
    });
  }

  const testF = async()=>{
    const fetch = require('node-fetch');

    fetch('https://api.trello.com/1/boards/{id}?key=APIKey&token=APIToken', {
      method: 'GET',
      headers: {
        'Accept': 'application/json'
      }
    })
    .then(response => {
      console.log(
        `Response: ${response.status} ${response.statusText}`
      );
      return response.text();
    })
    .then(text => console.log(text))
    .catch(err => console.error(err));
    }

  return (
    <div className="App">
      <h1>Welcome</h1>
      <button onClick={handleLogin}>
        點我使用該死的授權
      </button>
      <br />
      <button onClick={testF}>
        測試按鈕
      </button>
      <div></div>
    </div>
  );
}

export default App;
